// Private file storage behind a small interface, so local disk can be swapped for an object store
// (S3, Azure Blob, Google Cloud Storage) in production without touching the rest of the app.
// Files are never served from a public folder: they are only reachable through the authorized download route.
import crypto from "node:crypto";
import fs from "node:fs/promises";
import path from "node:path";

export interface StorageProvider {
  put(key: string, bytes: Buffer): Promise<void>;
  get(key: string): Promise<Buffer>;
  delete(key: string): Promise<void>;
}

// Keys are generated by the server: year/month/random id. Anything else is refused, so a key can never climb out of the folder.
const KEY = /^\d{4}\/\d{2}\/[0-9a-f]{32}$/;
export const newStorageKey = (now = new Date()) =>
  `${now.getUTCFullYear()}/${String(now.getUTCMonth() + 1).padStart(2, "0")}/${crypto.randomBytes(16).toString("hex")}`;

export class LocalDiskStorage implements StorageProvider {
  constructor(private root: string) {}
  private resolve(key: string) {
    if (!KEY.test(key)) throw new Error("Invalid storage key");
    const p = path.resolve(this.root, key);
    if (!p.startsWith(path.resolve(this.root) + path.sep)) throw new Error("Invalid storage key");
    return p;
  }
  async put(key: string, bytes: Buffer) {
    const p = this.resolve(key);
    await fs.mkdir(path.dirname(p), { recursive: true });
    await fs.writeFile(p, bytes, { flag: "wx" }); // never overwrite an existing file
  }
  async get(key: string) {
    return fs.readFile(this.resolve(key));
  }
  async delete(key: string) {
    await fs.rm(this.resolve(key), { force: true });
  }
}

export class MemoryStorage implements StorageProvider {
  files = new Map<string, Buffer>();
  async put(key: string, bytes: Buffer) {
    if (!KEY.test(key)) throw new Error("Invalid storage key");
    if (this.files.has(key)) throw new Error("exists");
    this.files.set(key, bytes);
  }
  async get(key: string) {
    const b = this.files.get(key);
    if (!b) throw new Error("not found");
    return b;
  }
  async delete(key: string) {
    this.files.delete(key);
  }
}

// The default provider for this deployment. Set STORAGE_DIR to a folder outside the code (and back it up with the database).
export function defaultStorage(): StorageProvider {
  return new LocalDiskStorage(process.env.STORAGE_DIR ?? path.resolve(process.cwd(), ".data", "files"));
}
